// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._appliedIds = new Set();
    this._bufferedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    const seq = event.seq;
    const id = event.id;

    // Stale seq: already applied
    if (seq <= this.lastSeq) {
      return [];
    }

    // Idempotent: id already applied
    if (this._appliedIds.has(id)) {
      return [];
    }

    // Idempotent: id already buffered
    if (this._bufferedIds.has(id)) {
      return [];
    }

    // Duplicate seq already buffered (different id)
    if (this._buffer.has(seq)) {
      return [];
    }

    const appliedNow = [];

    if (seq === this.lastSeq + 1) {
      this.apply(event);
      this._appliedIds.add(id);
      this.lastSeq = seq;
      appliedNow.push(event);

      let nextSeq = this.lastSeq + 1;
      while (this._buffer.has(nextSeq)) {
        const nextEvent = this._buffer.get(nextSeq);
        this._buffer.delete(nextSeq);
        this._bufferedIds.delete(nextEvent.id);
        this.apply(nextEvent);
        this._appliedIds.add(nextEvent.id);
        this.lastSeq = nextSeq;
        appliedNow.push(nextEvent);
        nextSeq = this.lastSeq + 1;
      }
    } else {
      // Future seq, buffer it
      this._buffer.set(seq, event);
      this._bufferedIds.add(id);
    }

    return appliedNow;
  }
}

