// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._bufferedIds = new Set();
    this._appliedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Idempotency by id
    if (this._appliedIds.has(event.id)) return [];
    if (this._bufferedIds.has(event.id)) return [];

    // Stale seq already applied (includes seq < startSeq because lastSeq = startSeq-1)
    if (event.seq <= this.lastSeq) return [];

    // Duplicate seq already buffered (different id with same seq)
    if (this._buffer.has(event.seq)) return [];

    // Not the next expected seq -> buffer
    if (event.seq !== this.lastSeq + 1) {
      this._buffer.set(event.seq, event);
      this._bufferedIds.add(event.id);
      return [];
    }

    // Apply this event and drain contiguous buffered events
    const applied = [];
    let current = event;
    while (current) {
      this.apply(current);
      this._appliedIds.add(current.id);
      this.lastSeq = current.seq;
      applied.push(current);

      const nextSeq = this.lastSeq + 1;
      if (this._buffer.has(nextSeq)) {
        const nextEvent = this._buffer.get(nextSeq);
        this._buffer.delete(nextSeq);
        this._bufferedIds.delete(nextEvent.id);
        current = nextEvent;
      } else {
        current = null;
      }
    }
    return applied;
  }
}

