      if (e.effect !== 'allow') continue;
      const key = `${e.principal}\0${e.role}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (cur === node) {
        lines.push(`${e.principal}: ${e.role}`);
      } else {
        lines.push(`${e.principal}: ${e.role} (inherited from ${cur.path()})`);
      }
    }
    if (cur.inherit === false) break;
    cur = cur.parent;
  }
  return lines.sort();
}

