function makeNeedsQuoting(d) {
  return (s) => s.includes(d.delimiter) || s.includes(d.quote) || s.includes('\r') || s.includes('\n');
}

/** rows: any[][] -> CSV text (always ends with a line terminator). null/undefined -> empty field. */
export function stringify(rows, opts = {}) {
  const d = resolveDialect(opts);
  const needsQuoting = makeNeedsQuoting(d);
  const cell = (v) => {
    let s;
    if (v == null) s = '';
    else if (typeof v === 'number') {
      s = String(v);
      if (d.decimal !== '.') {
        s = s.replace('.', d.decimal);
      }
    } else {
      s = String(v);
    }
    return needsQuoting(s) ? d.quote + s.split(d.quote).join(d.quote + d.quote) + d.quote : s;
  };
  return rows.map((r) => r.map(cell).join(d.delimiter)).join(d.lineTerminator) + d.lineTerminator;
}

/**
 * CSV text -> string[][]. Accepts CRLF or LF line endings. Quoted fields may contain
 * commas, doubled quotes and newlines. A trailing newline does not produce an empty row.
 */
export function parse(text, opts = {}) {
  const d = resolveDialect(opts);
  const delimiter = d.delimiter;
  const quote = d.quote;
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === quote) {
        if (text[i + 1] === quote) { field += quote; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += ch; i++; continue;
    }
    if (ch === quote && field === '') { inQuotes = true; i++; continue; }
    if (ch === delimiter) { row.push(field); field = ''; i++; continue; }
    if (ch === '\r' && text[i + 1] === '\n') { i++; continue; }
    if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; i++; continue; }
    field += ch; i++;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows;
}

