export function importBankFile(text, opts = {}) {
  const { dialect = 'excel', ...overrides } = opts;
  const d = resolveDialect({ dialect, ...overrides });
  const [header, ...rows] = parse(text, { dialect, ...overrides });
  if (!header) return [];
  const idx = Object.fromEntries(header.map((h, i) => [h.trim(), i]));
  return rows.map((r) => {
    let amtStr = r[idx.amount] ?? '';
    if (d.decimal !== '.') {
      amtStr = amtStr.split(d.decimal).join('.');
    }
    return {
      date: r[idx.date],
      description: r[idx.description],
      amount: Number(amtStr),
